(function(root){'use strict';
const money=v=>{if(typeof v!=='string'||!/^\d{1,7}(\.\d{1,2})?$/.test(v)||Number(v)>1000000)throw Error('Enter every money amount as 0–1,000,000 USD, with at most two decimal places and no commas.');return Math.round(Number(v)*100)};
function validate(config,input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Invalid input object.');const keys=['name','start','end','basis',...config.fields.map(f=>f[0])];if(Object.keys(input).length!==keys.length||keys.some(k=>!Object.hasOwn(input,k)))throw Error('Backup fields do not match this worksheet.');for(const k of ['name','basis'])if(typeof input[k]!=='string'||!input[k].trim()||input[k].length>(k==='name'?100:500)||/[\u0000-\u001f]/.test(input[k]))throw Error('Enter a name and basis/assumptions without control characters.');
const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&s>='1900-01-01'&&s<='2200-12-31'&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s;
if(!date(input.start)||!date(input.end)||input.start>input.end)throw Error('Enter real dates from 1900 to 2200, with end on or after start.');const values={};for(const [k]of config.fields){if(k==='months'){if(typeof input[k]!=='string'||!/^([1-9]|1\d|2[0-4])$/.test(input[k]))throw Error('Trading months must be a whole number from 1 to 24.');values[k]=Number(input[k]);}else values[k]=money(input[k]);}if(config.slug==='income-statement-template'&&values.returns>values.sales)throw Error('Returns cannot exceed sales in this simplified worksheet.');return values;}
function calculate(config,input){const v=validate(config,input);let out=[];if(config.slug==='startup-budget-template'){const uses=v.equipment+v.setup+v.deposits+v.contingency,net=v.monthlyPayments-v.monthlyReceipts,short=Math.max(0,net)*v.months,target=uses+short+v.reserve;out=[uses,net,short,target,v.funding-target,v.funding-uses-net*v.months];}else out=config.report.map(([label,expr])=>{let sum=0;for(const token of expr.match(/[+-]?[A-Za-z]+/g)){const sign=token[0]==='-'?-1:1;const key=token.replace(/^[+-]/,'');if(!Object.hasOwn(v,key))throw Error('Unsupported formula.');sum+=sign*v[key];}return sum;});if(out.some(x=>!Number.isSafeInteger(x)))throw Error('Result exceeds supported precision.');return out.map((amount,i)=>({label:config.report[i][0],cents:amount}));}
const safe=x=>{let s=String(x);return /^[\s]*[=+\-@]/.test(s)?"'"+s:s;};const csv=rows=>rows.map(r=>r.map(c=>'"'+safe(c).replace(/"/g,'""')+'"').join(',')).join('\r\n');
const api={validate,calculate,csv};if(typeof module==='object'&&module.exports)module.exports=api;if(!root.document)return;root.NexalyFinance=api;
const doc=root.document,el=id=>doc.getElementById(id),configNode=el('finance-config');if(!configNode)return;const config=JSON.parse(configNode.textContent),form=el('fin-form'),status=el('fin-status'),result=el('fin-result');let reviewed=null,pending=null;const keys=['name','start','end','basis',...config.fields.map(f=>f[0])];
function read(){return Object.fromEntries(keys.map(k=>[k,el('fin-'+k).value]));}function invalidate(){reviewed=null;result.replaceChildren();el('fin-csv').disabled=true;el('fin-print').disabled=true;status.textContent='Inputs changed. Review again before exporting.';}function fill(x){keys.forEach(k=>el('fin-'+k).value=x[k]);invalidate();}
function exportFile(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=doc.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function request(x,label){pending=x;el('fin-replace-label').textContent=label;el('fin-dialog').showModal();}
form.addEventListener('input',invalidate);form.addEventListener('change',invalidate);form.addEventListener('submit',event=>{event.preventDefault();try{const input=read(),out=calculate(config,input);result.replaceChildren();let title=doc.createElement('h3');title.textContent=input.name;result.append(title);for(const text of [input.start+' to '+input.end+' · USD','Basis / assumptions: '+input.basis]){let p=doc.createElement('p');p.textContent=text;result.append(p);}let table=doc.createElement('table'),cap=doc.createElement('caption');cap.textContent='Reviewed results (USD)';table.append(cap);const tbody=doc.createElement('tbody');for(const x of out){let tr=doc.createElement('tr'),th=doc.createElement('th'),td=doc.createElement('td');th.scope='row';th.textContent=x.label;td.textContent=(x.cents/100).toLocaleString('en-US',{style:'currency',currency:'USD'});tr.append(th,td);tbody.append(tr);}table.append(tbody);let wrap=doc.createElement('div');wrap.className='table-wrap';wrap.tabIndex=0;wrap.append(table);result.append(wrap);let p=doc.createElement('p');p.textContent=config.slug==='cash-flow-statement-template'?(out.at(-1).cents===0?'Entered closing cash reconciles under this limited model; classifications and completeness still need review.':'Closing cash does not reconcile. Investigate records, account scope and cutoff; do not plug the difference.'):config.slug==='startup-budget-template'?'Funding target includes retained cash, not an extra expense. This model does not test daily solvency.':'Calculated profit is not bank cash; this limited worksheet does not verify classifications.';result.append(p);reviewed={input,out};el('fin-csv').disabled=false;el('fin-print').disabled=false;status.textContent='Reviewed. Check assumptions, supported categories and source evidence before sharing.';}catch(e){invalidate();status.textContent=e.message;}});
el('fin-sample').addEventListener('click',()=>request(Object.assign({name:'Fictional '+config.slug,start:'2026-11-01',end:'2026-11-30',basis:config.slug==='startup-budget-template'?'Constant monthly USD assumptions over 3 trading months; dates label the preparation window, not the full trading horizon.':'Simplified historical USD example; listed categories only; excluded items described in the guide.'},Object.fromEntries(config.fields.map(f=>[f[0],String(f[2])]))),'Replace current entries with the fictional example?'));
el('fin-clear').addEventListener('click',()=>request(Object.fromEntries(keys.map(k=>[k,''])),'Clear all entries? Download a backup first if needed.'));
el('fin-cancel').addEventListener('click',()=>{pending=null;el('fin-dialog').close();});el('fin-confirm').addEventListener('click',()=>{if(pending)fill(pending);pending=null;el('fin-dialog').close();status.textContent='Entries replaced. Review to calculate results.';});el('fin-dialog').addEventListener('cancel',()=>{pending=null;});
el('fin-backup').addEventListener('click',()=>{try{let input=read();validate(config,input);exportFile(JSON.stringify({tool:config.slug,version:1,input},null,2),config.slug+'.json','application/json');status.textContent='Valid input backup downloaded. This does not certify the records.';}catch(e){status.textContent=e.message;}});
el('fin-import').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>32768)throw Error('Backup exceeds 32 KB.');const b=JSON.parse(await file.text());if(!b||Object.keys(b).sort().join(',')!=='input,tool,version'||b.tool!==config.slug||b.version!==1)throw Error('Choose a version-1 backup from this exact worksheet.');validate(config,b.input);request(b.input,'Replace all entries with this validated backup?');}catch(e){status.textContent='Import rejected: '+e.message;}finally{event.target.value='';}});
el('fin-csv').addEventListener('click',()=>{if(!reviewed)return;exportFile('\uFEFF'+csv([['Worksheet',config.title],['Name',reviewed.input.name],['Start',reviewed.input.start],['End',reviewed.input.end],['Currency','USD'],['Basis',reviewed.input.basis],['Section','Field','Value'],...config.fields.map(([k,l])=>['Input',l,reviewed.input[k]]),...reviewed.out.map(x=>['Result',x.label,(x.cents/100).toFixed(2)]),['Scope',config.scope],['Formula',config.formula]]),config.slug+'-reviewed.csv','text/csv;charset=utf-8');});el('fin-print').addEventListener('click',()=>{if(reviewed)root.print();});
})(typeof window!=='undefined'?window:globalThis);
